#include <cassert>
#include <cmath>
#include <vector>
#include <tuple>
#include <iostream>
#include <utility>

static std::size_t dropout_draw_idx = 0;

double next_dropout_draw() {
    assert(dropout_draw_idx < DROPOUT_DRAWS.size());
    return DROPOUT_DRAWS[dropout_draw_idx++];
}

double sigmoid(double x) {
    if (x < -500.0) return 0.0;
    if (x > 500.0) return 1.0;
    return 1.0 / (1.0 + std::exp(-x));
}

double sigmoid_derivative(double s) { return s * (1.0 - s); }

struct SimpleNetwork {
    int hidden_dim;
    bool use_dropout;
    double dropout_rate;
    std::vector<std::vector<double>> w1;
    std::vector<double> b1;
    std::vector<double> w2;
    double b2;

    SimpleNetwork(const std::vector<std::vector<double>>& init_w1,
                  const std::vector<double>& init_b1,
                  const std::vector<double>& init_w2,
                  double init_b2,
                  bool use_dropout_, double dropout_rate_)
        : hidden_dim(static_cast<int>(init_w1.size())), use_dropout(use_dropout_), dropout_rate(dropout_rate_),
          w1(init_w1), b1(init_b1), w2(init_w2), b2(init_b2) {}

    std::tuple<double, std::vector<double>, std::vector<double>> forward(const std::vector<double>& x, bool training = true) {
        std::vector<double> z1(hidden_dim), h(hidden_dim);
        for (int i = 0; i < hidden_dim; ++i) {
            double s = b1[i];
            for (int j = 0; j < 4; ++j) s += w1[i][j] * x[j];
            z1[i] = s;
            h[i] = sigmoid(z1[i]);
        }

        std::vector<double> mask(hidden_dim, 1.0);
        if (use_dropout && training) {
            for (int i = 0; i < hidden_dim; ++i) {
                mask[i] = next_dropout_draw() > dropout_rate ? 1.0 : 0.0;
            }
        }

        std::vector<double> h_drop(hidden_dim);
        for (int i = 0; i < hidden_dim; ++i) h_drop[i] = h[i] * mask[i];

        double z2 = b2;
        for (int i = 0; i < hidden_dim; ++i) z2 += w2[i] * h_drop[i];
        double y = sigmoid(z2);
        return {y, h, mask};
    }

    void backward(const std::vector<double>& x, double y_true, double y_pred, const std::vector<double>& h, const std::vector<double>& mask, double lr) {
        double dy = y_pred - y_true;
        for (int i = 0; i < hidden_dim; ++i) {
            w2[i] -= lr * dy * h[i] * mask[i];
        }
        b2 -= lr * dy;
        for (int i = 0; i < hidden_dim; ++i) {
            double grad = dy * w2[i] * sigmoid_derivative(h[i]) * mask[i];
            for (int j = 0; j < 4; ++j) w1[i][j] -= lr * grad * x[j];
            b1[i] -= lr * grad;
        }
    }

    double train(const std::vector<std::pair<std::vector<double>, double>>& train_data, int epochs, double lr) {
        for (int e = 0; e < epochs; ++e) {
            for (const auto& sample : train_data) {
                auto fwd_train = forward(sample.first, true);
                double y_pred = std::get<0>(fwd_train);
                const auto& h = std::get<1>(fwd_train);
                const auto& mask = std::get<2>(fwd_train);
                backward(sample.first, sample.second, y_pred, h, mask, lr);
            }
        }
        double total_loss = 0.0;
        for (const auto& sample : train_data) {
            auto fwd_val = forward(sample.first, false);
            double y_pred = std::get<0>(fwd_val);
            total_loss += (y_pred - sample.second) * (y_pred - sample.second) / 2.0;
        }
        return train_data.empty() ? 0.0 : total_loss / static_cast<double>(train_data.size());
    }

    std::pair<double, int> evaluate(const std::vector<std::pair<std::vector<double>, double>>& data) {
        double total_loss = 0.0;
        int correct = 0;
        for (const auto& sample : data) {
            auto fwd_val = forward(sample.first, false);
            double y_pred = std::get<0>(fwd_val);
            total_loss += (y_pred - sample.second) * (y_pred - sample.second) / 2.0;
            int pred_class = y_pred > 0.5 ? 1 : 0;
            if (pred_class == static_cast<int>(sample.second)) correct += 1;
        }
        return {data.empty() ? 0.0 : total_loss / static_cast<double>(data.size()), correct};
    }
};

int main() {
    std::cout << "Training without dropout:\n";
    SimpleNetwork net_no_dropout(W1_ND, B1_ND, W2_ND, B2_ND, false, 0.0);
    double no_dropout_loss = net_no_dropout.train(PY_TRAIN, 60, 0.5);
    auto no_dropout_eval = net_no_dropout.evaluate(PY_VAL);
    double no_dropout_val_loss = no_dropout_eval.first;
    int no_dropout_acc = no_dropout_eval.second;

    std::cout << "Training with dropout:\n";
    SimpleNetwork net_with_dropout(W1_WD, B1_WD, W2_WD, B2_WD, true, 0.15);
    double dropout_loss = net_with_dropout.train(PY_TRAIN, 80, 0.5);
    auto dropout_eval = net_with_dropout.evaluate(PY_VAL);
    double dropout_val_loss = dropout_eval.first;
    int dropout_acc = dropout_eval.second;

    std::cout << "No dropout:  train_loss=" << no_dropout_loss << ", val_loss=" << no_dropout_val_loss << ", accuracy=" << no_dropout_acc << "/" << PY_VAL.size() << "\n";
    std::cout << "With dropout: train_loss=" << dropout_loss << ", val_loss=" << dropout_val_loss << ", accuracy=" << dropout_acc << "/" << PY_VAL.size() << "\n";

    double no_dropout_gap = no_dropout_val_loss - no_dropout_loss;
    double dropout_gap = dropout_val_loss - dropout_loss;
    std::cout << "Generalization gap (train-val loss):\n";
    std::cout << "  No dropout: " << no_dropout_gap << "\n";
    std::cout << "  With dropout: " << dropout_gap << "\n";

    assert(dropout_gap <= no_dropout_gap);

    std::cout << "PASS\n";
    return 0;
}